/** Types for the Pipefetch client. Fields YouTube does not provide for an item are null, never missing. */

export declare const VERSION: string;

export interface PipefetchOptions {
  /** Your API key. Defaults to the PIPEFETCH_API_KEY environment variable. */
  apiKey?: string;
  /** Defaults to https://pipefetch.com */
  baseUrl?: string;
  /** How long to wait for one answer. Defaults to 90,000. */
  timeoutMs?: number;
  /** How many times to try again after a network failure, a 502, 503 or 504, or a per-minute rate limit. Defaults to 2. */
  retries?: number;
  /** Wait before the first retry; it doubles for each further one. Defaults to 1,000. */
  retryDelayMs?: number;
  /** A fetch implementation, for runtimes without a global one or for tests. */
  fetch?: typeof fetch;
}

export interface Credits {
  used: number;
  remaining: number;
}

export interface TranscriptOptions {
  /** Preferred caption language code, such as "en" or "pt-BR". Without it you get the video's original language. */
  lang?: string;
  /** What the text field holds. Defaults to "text". */
  format?: 'text' | 'timestamped' | 'srt' | 'vtt';
  /** Include the list of timed segments. Defaults to true. */
  segments?: boolean;
}

export interface Transcript {
  videoId: string;
  url: string;
  title: string | null;
  channel: { id: string | null; name: string | null; handle: string | null; url: string | null } | null;
  publishedAt: string | null;
  durationSeconds: number | null;
  language: string;
  languageName: string | null;
  isAutoGenerated: boolean;
  isPreferredLanguage: boolean;
  availableLanguages: { code: string; name: string; isAutoGenerated: boolean }[];
  format: 'text' | 'timestamped' | 'srt' | 'vtt';
  text: string;
  wordCount: number | null;
  segments?: { start: number; duration: number; text: string }[];
  chapters: { title: string; startSeconds: number; endSeconds: number | null }[];
}

export interface Video {
  videoId: string;
  url: string;
  title: string | null;
  description: string | null;
  publishedAt: string | null;
  durationSeconds: number | null;
  viewCount: number | null;
  likeCount: number | null;
  commentCount: number | null;
  category: string | null;
  keywords: string[];
  hashtags: string[];
  chapters: { title: string; startSeconds: number }[];
  thumbnailUrl: string | null;
  isLive: boolean | null;
  isUpcoming: boolean | null;
  isFamilySafe: boolean | null;
  isAgeRestricted: boolean | null;
  commentsTurnedOff: boolean | null;
  channel: {
    id: string | null;
    name: string | null;
    handle: string | null;
    url: string | null;
    isVerified: boolean | null;
    avatarUrl: string | null;
    subscriberCount: number | null;
  } | null;
}

export interface Channel {
  id: string;
  handle: string | null;
  title: string | null;
  url: string;
  description: string | null;
  keywords: string[];
  /** The rounded figure YouTube publishes, such as 21400000 for "21.4M". */
  subscriberCount: number | null;
  videoCount: number | null;
  avatarUrl: string | null;
  rssUrl: string | null;
  isFamilySafe: boolean | null;
}

export interface ChannelVideosOptions {
  /** How many of the latest uploads to return: 1 to 30. Defaults to 30. */
  limit?: number;
}

export interface ChannelVideos {
  channel: Channel;
  videos: {
    videoId: string;
    url: string;
    title: string | null;
    publishedAt: string | null;
    publishedText: string | null;
    durationSeconds: number | null;
    viewCount: number | null;
    /** False when the count is YouTube's rounded display value. */
    viewCountIsExact: boolean;
    isShort: boolean;
    isLive: boolean;
    thumbnailUrl: string | null;
  }[];
}

export interface ChannelShortsOptions {
  /** How many of the latest Shorts to return: 1 to 40. Defaults to 20. */
  limit?: number;
}

export interface ChannelShorts {
  channel: { id: string | null; name: string | null; url: string | null };
  shorts: {
    videoId: string;
    url: string;
    title: string | null;
    viewCount: number | null;
    viewCountIsExact: boolean;
    thumbnailUrl: string | null;
  }[];
}

export interface SearchOptions {
  /** How many results to return: 1 to 40. Defaults to 20. */
  limit?: number;
  /** Kind of result. Defaults to "video". */
  type?: 'video' | 'short' | 'channel' | 'playlist' | 'all';
  /** Result order. Defaults to "relevance". */
  sort?: 'relevance' | 'popularity' | 'newest' | 'mostViewed';
  /** Only results uploaded within this period. */
  uploaded?: 'hour' | 'today' | 'week' | 'month' | 'year';
  /** Two-letter country code the search is run for. */
  country?: string;
  /** Interface language code for titles and labels. */
  lang?: string;
}

export interface SearchResults {
  query: string;
  /** Video results have the fields listed here; channel and playlist results carry their own. */
  results: {
    type: 'video' | 'short' | 'channel' | 'playlist';
    id: string;
    url: string;
    title: string | null;
    description?: string | null;
    publishedAt?: string | null;
    publishedAtPrecision?: string | null;
    durationSeconds?: number | null;
    viewCount?: number | null;
    viewCountIsExact?: boolean;
    isLive?: boolean;
    thumbnailUrl?: string | null;
    position: number;
    channel?: { id: string | null; name: string | null; handle: string | null; url: string | null; isVerified: boolean | null } | null;
    [field: string]: unknown;
  }[];
}

export interface CommentsOptions {
  /** How many comments to return: 1 to 100. Defaults to 20. Every started 20 cost 1 credit. */
  limit?: number;
  /** Top comments first, or newest first. Defaults to "top". */
  sort?: 'top' | 'newest';
}

export interface Comments {
  videoId: string;
  totalComments: number | null;
  /** Top-level comments only; replyCount says how many replies each one has. */
  comments: {
    id: string;
    text: string;
    likeCount: number | null;
    replyCount: number | null;
    publishedText: string | null;
    isPinned: boolean;
    isHeartedByCreator: boolean;
    author: {
      name: string | null;
      channelId: string | null;
      channelUrl: string | null;
      avatarUrl: string | null;
      isVerified: boolean;
      isChannelOwner: boolean;
    };
  }[];
}

export interface WebsiteContactsOptions {
  /** How many pages of the site to read, contact, imprint and about pages first: 1 to 10. Defaults to 5. */
  pages?: number;
}

export interface WebsiteContacts {
  /** The page the reading started from, after redirects. */
  url: string;
  domain: string | null;
  companyName: string | null;
  /** The best address for writing to the company: on the website's own domain first, then shared mailboxes. */
  primaryEmail: string | null;
  primaryPhone: string | null;
  emails: {
    email: string;
    /** "role" is a shared mailbox (info@, sales@), "personal" a person's address. */
    type: 'role' | 'personal' | null;
    onWebsiteDomain: boolean;
    /** Gmail, Outlook and other free mailbox providers. */
    freeProvider: boolean;
    /** Whether the address's domain has mail servers; null when it could not be checked. */
    mxFound: boolean | null;
    foundOn: string[];
  }[];
  phones: {
    /** International format (+4930123456) when the number is valid for its country. */
    phone: string;
    national: string | null;
    country: string | null;
    lineType: string | null;
    source: 'link' | 'structured_data' | 'text' | null;
    foundOn: string[];
  }[];
  /** Numbers found in the page text with no phone label next to them. Check before use. */
  phonesUncertain: string[];
  /** Profile addresses per platform; an empty list where the site links none. */
  socials: Record<
    | 'linkedin' | 'facebook' | 'instagram' | 'twitter' | 'youtube' | 'tiktok' | 'pinterest' | 'threads'
    | 'snapchat' | 'telegram' | 'whatsapp' | 'discord' | 'reddit' | 'github' | 'bluesky' | 'medium',
    string[]
  >;
  contactPageUrl: string | null;
  contactFormUrl: string | null;
  hasContactForm: boolean;
  address: string | null;
  country: string | null;
  language: string | null;
  description: string | null;
  logoUrl: string | null;
  /** The pages that were read. */
  pagesRead: string[];
}

export interface WebsiteBrand {
  url: string;
  domain: string;
  /** The company name the site states, or the part of its title that matches the domain; null rather than a guess. */
  name: string | null;
  title: string | null;
  description: string | null;
  /** null when the site draws its logo with CSS only: use `icon` then. */
  logo: {
    /** An image address, or a `data:` URI for a logo drawn as inline SVG. Both work as an image source. */
    url: string;
    format: string | null;
    /** Where it was found: the site's structured data, its header or home link, or elsewhere on the page. */
    source: 'structured-data' | 'header' | 'page' | null;
  } | null;
  /** The site icon. */
  icon: string | null;
  icons: string[];
  /** The image the site shows when it is shared on social media. */
  image: string | null;
  colors: {
    primary: { hex: string; rgb: string | null } | null;
    secondary: { hex: string; rgb: string | null } | null;
    /** The theme color the site declares for browsers, when it does. */
    theme: string | null;
  };
  fonts: { family: string; source: string | null }[];
  socials: { platform: string; url: string }[];
  twitterHandle: string | null;
  /** Up to two large images from the home page. */
  images: string[];
}

export interface Account {
  email: string;
  credits: number;
}

/** Any error answer from the API, or a failure to reach it. Nothing is charged for an error. */
export declare class PipefetchError extends Error {
  /** HTTP status, or null when the API was not reached. */
  status: number | null;
  /** The API's error code, such as "no_transcript" or "insufficient_credits". */
  code: string | null;
}
/** 400: a parameter is missing, unknown or not allowed. */
export declare class InvalidRequestError extends PipefetchError {}
/** 401: the API key is missing or not valid. */
export declare class AuthenticationError extends PipefetchError {}
/** 402: the account has fewer credits than the request costs. */
export declare class InsufficientCreditsError extends PipefetchError {}
/** 404: there is nothing to return for this request. Not charged. */
export declare class NotFoundError extends PipefetchError {}
/** 429: too many requests in a minute, or too many requests today that found nothing. */
export declare class RateLimitError extends PipefetchError {}

export declare class Pipefetch {
  /** Pass the API key, or an options object. Without a key, PIPEFETCH_API_KEY is used. */
  constructor(options?: string | PipefetchOptions);
  /** Credits used by the last request that returned data, and the balance after it. */
  credits: Credits | null;
  /** The transcript of a video: plain text, timed segments, or a ready SRT / WebVTT file. 1 credit. */
  transcript(video: string, options?: TranscriptOptions): Promise<Transcript>;
  /** Exact views, likes and comment count, description, tags, chapters and channel of one video. 1 credit. */
  video(video: string): Promise<Video>;
  /** Subscribers, video count, description, keywords and avatar of a channel. 1 credit. */
  channel(channel: string): Promise<Channel>;
  /** The latest uploads of a channel, newest first (up to 30), with the channel itself. 1 credit. */
  channelVideos(channel: string, options?: ChannelVideosOptions): Promise<ChannelVideos>;
  /** The latest Shorts of a channel, newest first (up to 40). 1 credit. */
  channelShorts(channel: string, options?: ChannelShortsOptions): Promise<ChannelShorts>;
  /** YouTube search results for a query (up to 40), with sorting and filters. 1 credit. */
  search(query: string, options?: SearchOptions): Promise<SearchResults>;
  /** Top or newest comments of a video (up to 100). 1 credit per started 20 comments. */
  comments(video: string, options?: CommentsOptions): Promise<Comments>;
  /** The emails, phone numbers and social profiles a website publishes, with its contact page and address. 1 credit. */
  websiteContacts(url: string, options?: WebsiteContactsOptions): Promise<WebsiteContacts>;
  /** A company's logo, icon, brand colors, fonts, description and social profiles, read from its website. 1 credit. */
  websiteBrand(url: string): Promise<WebsiteBrand>;
  /** The account behind the key: its email and credit balance. Free. */
  account(): Promise<Account>;
}

export default Pipefetch;
